import zlib from 'zlib';
import { PDFArray, PDFDocument, PDFRawStream } from 'pdf-lib';

export interface ExtractedKarnePdf {
  rawId: string;
  normalizedId: string;
  candidateIds?: string[];
  studentName?: string;
  sourceFileName: string;
  pageNumber: number;
  position: 'top' | 'bottom' | 'full';
  pdfBuffer: Buffer;
}

/**
 * Parses individual OMR filenames generated by "[Ayrı PDF Oluştur]":
 * Examples:
 * - "010301_ION_POPESCU_Sonuc_Belgesi.pdf" -> rawId: "010301", normalizedId: "010301", studentName: "ION POPESCU"
 * - "10301_ION_POPESCU_Sonuc_Belgesi.pdf"  -> rawId: "10301",  normalizedId: "010301", studentName: "ION POPESCU"
 * - "010301_ION_POPESCU.pdf"               -> rawId: "010301", normalizedId: "010301", studentName: "ION POPESCU"
 * - "010301.pdf"                           -> rawId: "010301", normalizedId: "010301"
 */
export function parseIndividualOmrFilename(filename: string): {
  rawId: string;
  normalizedId: string;
  candidateIds: string[];
  studentName?: string;
} | null {
  const baseWithExt = filename.split(/[\\/]/).pop() || filename;
  const base = baseWithExt.replace(/\.pdf$/i, '').trim();

  // Check if filename starts with a 5-to-12 digit Student ID followed by optional "_NAME_SURNAME_Sonuc_Belgesi"
  const prefixMatch = base.match(/^(\d{5,12})(?:[_\-\s.]+(.*))?$/);
  if (prefixMatch) {
    const rawId = prefixMatch[1];
    const rest = (prefixMatch[2] || '').trim();

    const candidateSet = new Set<string>();
    if (rawId.length === 6) {
      candidateSet.add(rawId);
    } else if (rawId.length === 5) {
      candidateSet.add(rawId.padStart(6, '0'));
      candidateSet.add(rawId);
    } else {
      candidateSet.add(rawId);
      candidateSet.add(rawId.slice(-6));
      candidateSet.add(rawId.slice(0, 6));
      if (rawId.replace(/^0+/, '').length === 5) {
        candidateSet.add(rawId.replace(/^0+/, '').padStart(6, '0'));
      }
    }

    const candidates = Array.from(candidateSet);
    const normalizedId = candidates[0] || rawId;

    let studentName: string | undefined;
    if (rest) {
      const cleanedName = rest
        .replace(/[_\-\s]*(sonuc[_\-\s]*belgesi|sonuc|belgesi|karne|result|rapor)[_\-\s]*$/i, '')
        .replace(/[_\-]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
      if (cleanedName.length >= 2) {
        studentName = cleanedName;
      }
    }

    return {
      rawId,
      normalizedId,
      candidateIds: candidates,
      studentName,
    };
  }

  return null;
}

export function extractSixDigitIdFromFilename(filename: string): string | null {
  const parsed = parseIndividualOmrFilename(filename);
  if (parsed) return parsed.normalizedId;

  const base = filename.split(/[\\/]/).pop() || filename;
  const match6 = base.match(/(\d{6})/);
  if (match6) return match6[1];
  const match5 = base.match(/(?<!\d)(\d{5})(?!\d)/);
  if (match5) return match5[1].padStart(6, '0');
  return null;
}

function decodePdfStreamObject(streamObj: unknown): string {
  if (!streamObj || typeof streamObj !== 'object') return '';
  const raw = (streamObj as PDFRawStream).contents;
  if (!raw) return '';
  const buf = Buffer.from(raw);
  try {
    return zlib.inflateSync(buf).toString('latin1');
  } catch {
    return buf.toString('latin1');
  }
}

function extractTextTokensFromStream(streamText: string): string[] {
  const tokens: string[] = [];
  const regex = /\[([\s\S]*?)\]\s*TJ|\(([\s\S]*?)\)\s*Tj/g;
  let m: RegExpExecArray | null;
  while ((m = regex.exec(streamText)) !== null) {
    if (m[1] !== undefined) {
      const inner = m[1];
      const parts: string[] = [];
      const partRegex = /\((?:\\.|[^\\()])*\)/g;
      let pm: RegExpExecArray | null;
      while ((pm = partRegex.exec(inner)) !== null) {
        parts.push(pm[0].slice(1, -1));
      }
      tokens.push(parts.join(''));
    } else if (m[2] !== undefined) {
      tokens.push(m[2]);
    }
  }
  return tokens;
}

function parseCardsFromTokens(
  tokens: string[]
): Array<{ rawId: string; studentName?: string }> {
  const cards: Array<{ rawId: string; studentName?: string }> = [];

  for (let i = 0; i < tokens.length; i++) {
    const tok = tokens[i];
    if (tok.includes('Student Num') || tok.includes('Ogrenci No') || tok.includes('renci No')) {
      let foundId: string | null = null;
      for (let j = i + 1; j < Math.min(i + 7, tokens.length); j++) {
        const cand = tokens[j].trim();
        if (/^\d{4,12}$/.test(cand)) {
          foundId = cand;
          break;
        }
      }

      if (foundId) {
        let studentName: string | undefined;
        for (let k = Math.max(0, i - 18); k < i; k++) {
          const t = tokens[k].trim();
          const dateMatch = t.match(/^([A-ZА-ЯЁĂÂÎȘȚĞÜŞİÖÇ\s\-]{3,})\s+\d{2}\/\d{2}\/\d{4}$/i);
          if (dateMatch) {
            studentName = dateMatch[1].trim();
          }
        }
        cards.push({ rawId: foundId, studentName });
      }
    }
  }

  return cards;
}

export async function extractKarnesFromPdfBuffer(
  pdfBuffer: Buffer,
  fileName: string
): Promise<ExtractedKarnePdf[]> {
  const results: ExtractedKarnePdf[] = [];

  // 1) Check if the filename itself starts with the student's ID (e.g. "010301_ION_POPESCU_Sonuc_Belgesi.pdf" from "[Ayrı PDF Oluştur]")
  const filenameInfo = parseIndividualOmrFilename(fileName);

  let srcDoc: PDFDocument;
  try {
    srcDoc = await PDFDocument.load(pdfBuffer, { ignoreEncryption: true });
  } catch {
    if (filenameInfo) {
      results.push({
        rawId: filenameInfo.rawId,
        normalizedId: filenameInfo.normalizedId,
        candidateIds: filenameInfo.candidateIds,
        studentName: filenameInfo.studentName,
        sourceFileName: fileName,
        pageNumber: 1,
        position: 'full',
        pdfBuffer,
      });
      return results;
    }
    const fallbackId = extractSixDigitIdFromFilename(fileName);
    if (fallbackId) {
      results.push({
        rawId: fallbackId,
        normalizedId: fallbackId,
        candidateIds: [fallbackId],
        sourceFileName: fileName,
        pageNumber: 1,
        position: 'full',
        pdfBuffer,
      });
    }
    return results;
  }

  const pages = srcDoc.getPages();

  // If this is a 1-page individual PDF whose filename ALREADY starts with the Student ID (from "Ayrı PDF Oluştur"),
  // preserve the original PDF buffer intact and use the filename ID (plus any internal PDF ID as backup candidate).
  if (filenameInfo && pages.length === 1) {
    const page = pages[0];
    const contents = page.node.Contents();
    let pageStreamText = '';
    if (contents instanceof PDFArray) {
      for (let i = 0; i < contents.size(); i++) {
        const ref = contents.get(i);
        const streamObj = srcDoc.context.lookup(ref);
        pageStreamText += '\n' + decodePdfStreamObject(streamObj);
      }
    } else if (contents) {
      const streamObj = srcDoc.context.lookup(contents);
      pageStreamText = decodePdfStreamObject(streamObj);
    }
    const tokens = extractTextTokensFromStream(pageStreamText);
    const cards = parseCardsFromTokens(tokens);

    const candidateSet = new Set<string>(filenameInfo.candidateIds);
    for (const c of cards) {
      if (c.rawId.length === 5) candidateSet.add(c.rawId.padStart(6, '0'));
      candidateSet.add(c.rawId);
    }

    results.push({
      rawId: filenameInfo.normalizedId,
      normalizedId: filenameInfo.normalizedId,
      candidateIds: Array.from(candidateSet),
      studentName: filenameInfo.studentName || cards[0]?.studentName,
      sourceFileName: fileName,
      pageNumber: 1,
      position: 'full',
      pdfBuffer,
    });
    return results;
  }

  // 2) Otherwise, parse multi-page / 2-cards-per-page class PDFs (e.g. "6_KLASS_GENEL.pdf")
  for (let pIdx = 0; pIdx < pages.length; pIdx++) {
    const page = pages[pIdx];
    const contents = page.node.Contents();
    let pageStreamText = '';

    if (contents instanceof PDFArray) {
      for (let i = 0; i < contents.size(); i++) {
        const ref = contents.get(i);
        const streamObj = srcDoc.context.lookup(ref);
        pageStreamText += '\n' + decodePdfStreamObject(streamObj);
      }
    } else if (contents) {
      const streamObj = srcDoc.context.lookup(contents);
      pageStreamText = decodePdfStreamObject(streamObj);
    }

    const tokens = extractTextTokensFromStream(pageStreamText);
    const cards = parseCardsFromTokens(tokens);
    const { width, height } = page.getSize();
    const midY = height / 2 + 10; // ~431pt on A4 (841.98pt)

    if (cards.length >= 2) {
      // Top Card
      const topCard = cards[0];
      const topDoc = await PDFDocument.create();
      const [topPage] = await topDoc.copyPages(srcDoc, [pIdx]);
      topPage.setMediaBox(0, midY, width, height - midY);
      topPage.setCropBox(0, midY, width, height - midY);
      topDoc.addPage(topPage);
      const topBytes = await topDoc.save();
      const topNorm =
        topCard.rawId.length === 5 ? topCard.rawId.padStart(6, '0') : topCard.rawId;

      results.push({
        rawId: topCard.rawId,
        normalizedId: topNorm,
        candidateIds: [topNorm, topCard.rawId],
        studentName: topCard.studentName,
        sourceFileName: fileName,
        pageNumber: pIdx + 1,
        position: 'top',
        pdfBuffer: Buffer.from(topBytes),
      });

      // Bottom Card
      const botCard = cards[1];
      const botDoc = await PDFDocument.create();
      const [botPage] = await botDoc.copyPages(srcDoc, [pIdx]);
      botPage.setMediaBox(0, 20, width, midY - 20);
      botPage.setCropBox(0, 20, width, midY - 20);
      botDoc.addPage(botPage);
      const botBytes = await botDoc.save();
      const botNorm =
        botCard.rawId.length === 5 ? botCard.rawId.padStart(6, '0') : botCard.rawId;

      results.push({
        rawId: botCard.rawId,
        normalizedId: botNorm,
        candidateIds: [botNorm, botCard.rawId],
        studentName: botCard.studentName,
        sourceFileName: fileName,
        pageNumber: pIdx + 1,
        position: 'bottom',
        pdfBuffer: Buffer.from(botBytes),
      });
    } else if (cards.length === 1) {
      const singleCard = cards[0];
      const singleDoc = await PDFDocument.create();
      const [singlePage] = await singleDoc.copyPages(srcDoc, [pIdx]);

      const isTopHalfOmrLayout =
        pages.length > 1 &&
        height > 700 &&
        (pageStreamText.includes('451.22') || pageStreamText.includes('750.5'));

      if (isTopHalfOmrLayout) {
        singlePage.setMediaBox(0, midY, width, height - midY);
        singlePage.setCropBox(0, midY, width, height - midY);
      }

      singleDoc.addPage(singlePage);
      const singleBytes = await singleDoc.save();
      const singleNorm =
        singleCard.rawId.length === 5
          ? singleCard.rawId.padStart(6, '0')
          : singleCard.rawId;

      results.push({
        rawId: singleCard.rawId,
        normalizedId: singleNorm,
        candidateIds: [singleNorm, singleCard.rawId],
        studentName: singleCard.studentName,
        sourceFileName: fileName,
        pageNumber: pIdx + 1,
        position: isTopHalfOmrLayout ? 'top' : 'full',
        pdfBuffer: Buffer.from(singleBytes),
      });
    }
  }

  // Fallback to filename ID if no internal "Student Num." tokens were matched
  if (results.length === 0) {
    if (filenameInfo) {
      results.push({
        rawId: filenameInfo.rawId,
        normalizedId: filenameInfo.normalizedId,
        candidateIds: filenameInfo.candidateIds,
        studentName: filenameInfo.studentName,
        sourceFileName: fileName,
        pageNumber: 1,
        position: 'full',
        pdfBuffer,
      });
    } else {
      const fallbackId = extractSixDigitIdFromFilename(fileName);
      if (fallbackId) {
        results.push({
          rawId: fallbackId,
          normalizedId: fallbackId,
          candidateIds: [fallbackId],
          sourceFileName: fileName,
          pageNumber: 1,
          position: 'full',
          pdfBuffer,
        });
      }
    }
  }

  return results;
}
